def make_union_find(n):
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            # Replace x's parent with the representative of its current parent.
            parent[x] = {{compress}}
        return parent[x]

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        # Merge the two components by linking one ROOT to the other ROOT.
        {{merge}}
        return True

    return find, union

