def shortest_path_cost(graph, start, target):
    queue = deque([(start, 0)])
    seen = {start}

    while queue:
        node, cost = queue.popleft()
        if node == target:
            return cost

        for nxt, weight in graph.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, cost + weight))

    return -1

